                            removed=config.ignore_comments,
                            comment_prefix=config.comment_prefix,
                        )
                        comment_text = f" {comment}" if comment else ""
                        single_import_line += (
                            f"{(use_comments and ';') or config.comment_prefix}{comment_text}"
                        )
