                            reexport_rollback = 0
                        output_stream.write(sorted_code)
                        if is_reexport:
                            output_stream.truncate()
                        not_imports = True
                        code_sorting = False
                        code_sorting_section = ""
                        code_sorting_indent = ""
                        is_reexport = False
