        _output_stream = output_stream

        class DevNull(StringIO):
            def write(self, *a, **kw):
                pass

        output_stream = DevNull()

    if config.float_to_top:
        new_input = ""
        current = ""
        isort_off = False
        for line in chain(input_stream, (None,)):
            if isort_off and line is not None:
                if line == "# isort: on\n":
                    isort_off = False
